#include "stdlib/stats/base/dists/wald/quantile.h"
#include "stdlib/stats/base/dists/wald/cdf.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/constants/float64/pinf.h"

static const double MAX_ITERATIONS = 1e4;
static const double TOLERANCE = 1e-12;

/**
* Bisection method to find the quantile of a Wald distribution with mean `mu` and shape parameter `lambda` at a probability `p`.
*
* @param p         input value
* @param mu        mean
* @param lambda    shape parameter
* @return          evaluated quantile function
*/
static double wald_bisect( const double p, const double mu, const double lambda ) {
	double a;
	double b;
	double c;
	double m;
	double n;

	if ( p <= 0.0 ) {
		return 0.0;
	}
	if ( p >= 1.0 ) {
		return STDLIB_CONSTANT_FLOAT64_PINF;
	}
	// Establish an upper bound `b` such that `CDF(b) >= p`, while keeping `a` a lower bound for which `CDF(a) < p`:
	a = 0.0;
	b = mu;
	n = 1;
	while ( stdlib_base_dists_wald_cdf( b, mu, lambda ) < p && n < MAX_ITERATIONS ) {
		a = b;
		b *= 2.0;
		n += 1;
	}
	// Bisect the interval `[a,b]` until reaching the desired tolerance:
	n = 1;
	m = ( a + b ) / 2.0;
	while ( n < MAX_ITERATIONS ) {
		m = ( a + b ) / 2.0;
		if ( b - a < TOLERANCE ) {
			return m;
		}
		c = stdlib_base_dists_wald_cdf( m, mu, lambda );
		if ( p > c ) {
			a = m;
		} else {
			b = m;
		}
		n += 1;
	}
	return m;
}

/**
* Evaluates the quantile function for a Wald distribution with mean `mu` and shape parameter `lambda` at a probability `p`.
*
* @param p         input value
* @param mu        mean
* @param lambda    shape parameter
* @return          evaluated quantile function
*
* @example
* double y = stdlib_base_dists_wald_quantile( 0.8, 1.0, 1.0 );
* // returns ~1.448
*/
double stdlib_base_dists_wald_quantile( const double p, const double mu, const double lambda ) {
	if (
		stdlib_base_is_nan( p ) ||
		stdlib_base_is_nan( mu ) ||
		stdlib_base_is_nan( lambda ) ||
		mu <= 0.0 ||
		lambda < 0.0 ||
		p < 0.0 ||
		p > 1.0
	) {
		return 0.0 / 0.0; // NaN
	}
	if ( lambda == 0.0 ) {
		return mu;
	}
	return wald_bisect( p, mu, lambda );
}
